import { mapState } from "vuex";
import { printList, printForm, printSetStatus } from "@/api/setting";

export default {
  name: "specs",
  data() {
    return {
      grid: {
        xl: 10,
        lg: 10,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      optionsList: [
        {
          value: "0",
          label: "全部",
        },
        {
          value: "1",
          label: "易联云",
        },
        {
          value: "2",
          label: "飞鹅云",
        },
      ],
      columns: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "打印机名称",
          key: "print_name",
          minWidth: 100,
        },
        {
          title: "平台",
          slot: "type",
          minWidth: 100,
        },
        {
          title: "应用账号",
          slot: "account",
          minWidth: 100,
        },
        {
          title: "打印联数",
          key: "times",
          width: 200,
        },
        {
          title: "创建时间",
          key: "add_time",
          width: 200,
        },
        {
          title: "打印开关",
          slot: "status",
          width: 200,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          width: 140,
        },
      ],
      specsFrom: {
        page: 1,
        limit: 15,
        keyword: "",
        type: "0",
      },
      list: [],
      total: 0,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getList();
  },
  methods: {
    specsSearchs() {
      this.specsFrom.page = 1;
      this.list = [];
      this.getList();
    },

    // 单位列表
    getList() {
      this.loading = true;
      printList(this.specsFrom)
        .then((res) => {
          let data = res.data;
          this.list = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((err) => {
          this.loading = false;
          this.$Message.error(err.msg);
        });
    },
    pageChange(index) {
      this.specsFrom.page = index;
      this.getList();
    },
    // 修改是否显示
    onchangeIsShow(row) {
      let data = {
        id: row.id,
        status: row.status,
      };
      printSetStatus(data)
        .then(async (res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 添加
    add() {
      this.$modalForm(printForm(0)).then(() => {
        this.getList();
      });
    },
    //修改
    edit(id) {
      this.$modalForm(printForm(id)).then(() => {
        this.getList();
      });
    },
    setting(id) {
      this.$router.push({
        path: "/admin/setting/document/content",
        query: { id: id },
      });
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `print/del/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.list.splice(num, 1);
          if (!this.list.length) {
            this.specsFrom.page =
              this.specsFrom.page == 1 ? 1 : this.specsFrom.page - 1;
          }
          this.getList();
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
  },
};
